"""Same-object scalar FADDP S/D architecture and memory boundary."""
import json
RECORDS='\n#pragma once\n#include <stdint.h>\n#include <stdio.h>\n#include <string.h>\ntypedef struct{const char*name;unsigned width,rd,rn,rm,cond,original;} FADDPCase;\nstatic const FADDPCase cases[]={\n#define CASE(name,w,d,n,m,c,o) {#name,w,d,n,m,c,o},\n#include "faddp_cases.h"\n#undef CASE\n};\n#define CASE_COUNT ((unsigned)(sizeof(cases)/sizeof(cases[0])))\nstatic uint64_t get64(const uint8_t*p){uint64_t v;memcpy(&v,p,8);return v;}\nstatic void put64(uint8_t*p,uint64_t v){memcpy(p,&v,8);}\nstatic const uint64_t edges32[]={0,0x80000000,0x3f800000,0xbf800000,0x40000000,0xc0000000,0x7f7fffff,0xff7fffff,0x00800000,0x80800000,0x007fffff,0x807fffff,1,0x80000001,0x33800000,0xb3800000,0x337fffff,0x33800001,0x7f800000,0xff800000,0x7fc12345,0xffc54321,0x7f800123,0xff800456,0x3f800001,0xbf800001,0x3f7fffff,0xbf7fffff,0x00800001,0x80800001,0x00000123,0x80000456};\nstatic const uint64_t edges64[]={0,UINT64_C(0x8000000000000000),UINT64_C(0x3ff0000000000000),UINT64_C(0xbff0000000000000),UINT64_C(0x4000000000000000),UINT64_C(0xc000000000000000),UINT64_C(0x7fefffffffffffff),UINT64_C(0xffefffffffffffff),UINT64_C(0x0010000000000000),UINT64_C(0x8010000000000000),UINT64_C(0x000fffffffffffff),UINT64_C(0x800fffffffffffff),1,UINT64_C(0x8000000000000001),UINT64_C(0x3ca0000000000000),UINT64_C(0xbca0000000000000),UINT64_C(0x3c9fffffffffffff),UINT64_C(0x3ca0000000000001),UINT64_C(0x7ff0000000000000),UINT64_C(0xfff0000000000000),UINT64_C(0x7ff8123456789abc),UINT64_C(0xfff8abcde1234567),UINT64_C(0x7ff0000000000123),UINT64_C(0xfff0000000000456),UINT64_C(0x3ff0000000000001),UINT64_C(0xbff0000000000001),UINT64_C(0x3fefffffffffffff),UINT64_C(0xbfefffffffffffff),UINT64_C(0x0010000000000001),UINT64_C(0x8010000000000001),UINT64_C(0x123),UINT64_C(0x8000000000000456)};\nstatic const unsigned pairs[][2]={{0,0},{0,1},{1,0},{1,1},{2,3},{3,2},{2,4},{6,6},{7,7},{8,11},{12,12},{10,12},{2,14},{2,16},{2,17},{3,15},{18,18},{19,19},{18,19},{19,18},{20,21},{21,20},{20,22},{22,20},{20,23},{23,20},{22,23},{23,22},{18,20},{19,22},{8,13},{28,11},{0,3},{1,10},{2,17},{3,24},{4,31},{5,6},{6,13},{7,20},{8,27},{9,2},{10,9},{11,16},{12,23},{13,30},{14,5},{15,12},{16,19},{17,26},{18,1},{19,8},{20,15},{21,22},{22,29},{23,4},{24,11},{25,18},{26,25},{27,0},{28,7},{29,14},{30,21},{31,28}};\nstatic uint64_t hash800(const uint8_t*state){uint8_t normalized[800];memcpy(normalized,state,800);for(unsigned n=0;n<32;++n)if(n==0||n==1||n==18||n==30||n==31)put64(normalized+n*8,0);uint64_t h=UINT64_C(1469598103934665603);for(unsigned n=0;n<800;++n){h^=normalized[n];h*=UINT64_C(1099511628211);}return h;}\nstatic int run_faddp_records(void(*call)(unsigned,uint8_t*,const uint8_t*)){\n unsigned count=0;\n for(unsigned test=0;test<CASE_COUNT;++test)for(unsigned seed=0;seed<2048;++seed){\n  const FADDPCase*c=&cases[test];unsigned pattern=seed&63,mode=(seed>>6)&15,flags=(seed>>7)&15;\n  uint8_t input[768] __attribute__((aligned(16))),space[1664] __attribute__((aligned(16))),expected[800],original[768];uint8_t*out=space+32;\n  memset(input,0x73,sizeof(input));memset(space,0xab,sizeof(space));uint64_t random=UINT64_C(0x9e3779b97f4a7c15)^seed;\n  for(unsigned n=0;n<92;++n){random^=random<<13;random^=random>>7;random^=random<<17;put64(input+n*8,random);}\n  const uint64_t*edge=c->width==32?edges32:edges64;\n  for(unsigned n=0;n<2;++n){uint64_t v=edge[pairs[pattern][n]];memcpy(input+224+c->rn*16+n*(c->width/8),&v,c->width/8);}\n  put64(input+736,(uint64_t)flags<<28);put64(input+744,(seed&1024)?UINT64_C(0x0800009f):0);put64(input+752,((uint64_t)(mode&3)<<22)|((uint64_t)(mode&12)<<22));\n  memcpy(original,input,sizeof(input));call(test,out,input);\n  if(memcmp(original,input,sizeof(input)))return 20;\n  for(unsigned n=0;n<sizeof(space);++n)if((n<32||n>=1632)&&space[n]!=0xab)return 21;\n  if(get64(out)!=(uintptr_t)out||get64(out+8)!=(uintptr_t)input||!get64(out+240)||get64(out+248)%16)return 22;\n  for(unsigned reg=2;reg<30;++reg)if(reg!=18&&get64(out+reg*8)!=get64(input+(reg-2)*8))return 23;\n  if(memcmp(out+256,input+224,512)||get64(out+768)!=get64(input+736)||get64(out+776)!=get64(input+744)||get64(out+784)!=get64(input+752))return 24;\n  memcpy(expected,out,800);uint64_t selected=get64(out+800+256+c->rd*16);if(c->width==32)selected=(uint32_t)selected;\n  memset(expected+256+c->rd*16,0,16);memcpy(expected+256+c->rd*16,&selected,c->width/8);\n  uint64_t before=get64(out+776),after=get64(out+800+776);if((after&before)!=before||((after^before)&~UINT64_C(0x9d)))return 25;put64(expected+776,after);\n  if(memcmp(expected,out+800,800)){fprintf(stderr,"FADDP state/upperclear mismatch case=%s seed=%u\\n",c->name,seed);return 26;}\n  printf("RECORD %s %u %016llx %016llx %016llx\\n",c->name,seed,(unsigned long long)selected,(unsigned long long)hash800(out),(unsigned long long)hash800(out+800));++count;\n }\n printf("FADDP-RECORDS-SUCCESS %u\\n",count);return 0;\n}\n'
def generate(out):
 cases=[]
 for width in(32,64):
  for rd,rn in((0,0),(0,1),(17,31),(31,17)):
   word=(0x7e30d800 if width==32 else 0x7e70d800)|(rn<<5)|rd
   cases.append((f'faddp_{width}_{rd}_{rn}',width,rd,rn,0,0,int(word==0x7e30d800),[word]))
 lines=['.text']
 def function(name,body):lines.extend([f'.global {name}',f'.type {name},%function',f'{name}:','.cfi_startproc',*['  '+x for x in body],'.cfi_endproc',f'.size {name},.-{name}'])
 def snapshot(offset):
  b=[f'str x{r},[x0,#{offset+r*8}]'for r in range(31)]+[f'str q{r},[x0,#{offset+256+r*16}]'for r in range(32)]
  b+=['mov x2,sp',f'str x2,[x0,#{offset+248}]','cset x2,mi','lsl x2,x2,#31','cset x3,eq','orr x2,x2,x3,lsl#30','cset x3,cs','orr x2,x2,x3,lsl#29','cset x3,vs','orr x2,x2,x3,lsl#28',f'str x2,[x0,#{offset+768}]']
  for register,pos in(('fpsr',776),('fpcr',784)):b+=[f'mrs x2,{register}',f'str x2,[x0,#{offset+pos}]']
  return b+[f'ldr x2,[x0,#{offset+16}]',f'ldr x3,[x0,#{offset+24}]']
 for name,w,d,n,m,c,kind,words in cases:
  body=['sub sp,sp,#240']+[f'stp x{r},x{r+1},[sp,#{(r-18)*8}]'for r in range(18,30,2)]+['str x30,[sp,#96]']+[f'str q{r},[sp,#{112+(r-8)*16}]'for r in range(8,16)]
  for register,pos in(('fpsr',744),('fpcr',752)):body+=[f'ldr x2,[x1,#{pos}]',f'msr {register},x2']
  body +=[f'ldr q{r},[x1,#{224+r*16}]'for r in range(32)]+[f'ldr x{r},[x1,#{(r-2)*8}]'for r in range(2,30)if r!=18]
  body+=snapshot(0)+[f'.inst 0x{x:08x}'for x in words]+snapshot(800)
  body+=[f'ldr q{r},[sp,#{112+(r-8)*16}]'for r in range(8,16)]+[f'ldp x{r},x{r+1},[sp,#{(r-18)*8}]'for r in range(18,30,2)]+['ldr x30,[sp,#96]','add sp,sp,#240','ret']
  function(name,body);function('raw_'+name,[*[f'.inst 0x{x:08x}'for x in words],'ret'])
 function('faddp_control_copy',['ldr s0,[x0]','str s0,[x1]','ret'])
 (out/'faddp.S').write_text('\n'.join(lines)+'\n');(out/'faddp_cases.h').write_text(''.join(f'CASE({n},{w},{d},{rn},{rm},{c},{o})\n'for n,w,d,rn,rm,c,o,_ in cases));(out/'faddp_records.h').write_text(RECORDS);(out/'case-oracle.json').write_text(json.dumps(cases,indent=2)+'\n');return cases
